import { describe, it, expect } from 'vitest';
import { searchProducts } from '../src/lib/product-search';
import { quickOrderBlockMessage } from '../src/lib/quick-order-support';

describe('Product Search & Safety Tests', () => {
    it('should handle invalid limit gracefully', async () => {
        const res = await searchProducts('2330', 0);
        expect(res).toEqual([]);
    });
    it('should block warrants on quick order panels', () => {
        const msg = quickOrderBlockMessage('WRT', 'flash');
        expect(msg).toContain('權證不支援快速下單');
    });
});
